INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT144-S4-Q14$batch13$, 144, 4, 14, $batch13$Sufficient Assumption$batch13$, $batch13$Certain methods of creating high-quality counterfeit banknotes involve making accurate measurements of the images printed on genuine banknotes. Hence, if the production of high-quality counterfeit banknotes is to be prevented, some of the images on banknotes must be made very difficult or impossible to measure accurately.$batch13$, $batch13$The argument’s conclusion can be properly drawn if which one of the following is assumed?$batch13$, $batch13$B$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=144 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q14$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$Today’s copying technology is sophisticated enough to replicate almost any paper product with great precision.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q14$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$Once the images printed on a banknote have been measured accurately, there is no further impediment to the banknote’s being exactly replicated.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q14$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$Governments have better printing technology available to them than counterfeiters do.$batch13$, $batch13$Weakens$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q14$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$Few countries produce banknotes with images that are difficult for counterfeiters to measure accurately.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q14$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$New designs in banknotes generally lead to decreases in the amount of counterfeit currency in circulation.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q14$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q14$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$If high-quality counterfeiting is to be prevented, some banknote images must be very hard or impossible to measure accurately.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Some methods of making high-quality counterfeits rely on accurate measurement of the images on genuine notes.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$The conclusion makes blocking measurement a requirement. That follows only if measurement is the key step: once you can measure accurately, nothing else stops you. Then the only place to block counterfeiting is measurement.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Accurate measurement is enough to replicate a note.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT144-S4-Q14$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Good copying technology doesn't show that measurement is the step that must be blocked.$batch13$), ($batch13$B$batch13$, $batch13$If nothing else stands in the way after measurement, prevention has to happen at measurement.$batch13$), ($batch13$C$batch13$, $batch13$Better government printing suggests another line of defense besides measurement.$batch13$), ($batch13$D$batch13$, $batch13$What most countries do now doesn't show what prevention requires.$batch13$), ($batch13$E$batch13$, $batch13$New designs reducing counterfeiting doesn't make hard-to-measure images necessary.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT144-S4-Q14$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
